"""拼音层: 字符→无调拼音→折叠→掩码(精确整数键)

- 用 pypinyin(环境已装 0.55.0); 折叠组对齐本仓库 phon_match.py 的保守集合:
  声母 zh/z ch/c sh/s n/l r/l f/h j/q/x g/k; 韵母 an/ang en/eng in/ing ian/iang uan/uang o/uo ai/ei
  (刻意不折 t/d、b/p — phon_match 明确说这是不同音位)
- 音节 id 懒分配并随表持久化; 未见过的音节 → mask 返回 None(路由 MISS, 不猜)
- 表外字: 剩余位里放 codepoint 散列字段(禁止静默丢弃)
"""
from __future__ import annotations

try:
    from pypinyin import lazy_pinyin
    _HAS_PY = True
except Exception:  # 无 pypinyin 时退化为字面(仅自检可见)
    _HAS_PY = False

INITIALS = ["zh", "ch", "sh", "b", "p", "m", "f", "d", "t", "n", "l", "g", "k", "h",
            "j", "q", "x", "r", "z", "c", "s", "y", "w"]

# 折叠组 → 代表元(对齐 phon_match 的保守近似组)
INI_FOLD = {"zh": "z", "ch": "c", "sh": "s", "n": "l", "r": "l", "f": "h",
            "q": "j", "x": "j", "k": "g"}
FIN_FOLD = {"ang": "an", "eng": "en", "ing": "in", "iang": "ian", "uang": "uan",
            "uo": "o", "ei": "ai"}


def split_syl(syl: str):
    for ini in INITIALS:
        if syl.startswith(ini):
            return ini, syl[len(ini):]
    return "", syl


def fold_syl(syl: str) -> str:
    a, b = split_syl(syl)
    return INI_FOLD.get(a, a) + FIN_FOLD.get(b, b)


def syllable_of(ch: str):
    """单字 → 折叠后音节; 非汉字或失败 → None"""
    if not ("\u4e00" <= ch <= "\u9fff"):
        return None
    if not _HAS_PY:
        return None
    p = lazy_pinyin(ch, errors="ignore")
    if not p or not p[0]:
        return None
    return fold_syl(p[0])


def annotate(text: str) -> str:
    """给一串转写文本做拼音标注: 原字 + 折叠后音节(路由用的键), 便于人眼比对

    例: annotate("补农") → "bu<补> nong<农>"
    """
    out = []
    for ch in text or "":
        if "\u4e00" <= ch <= "\u9fff":
            if not _HAS_PY:
                out.append(ch)
                continue
            p = lazy_pinyin(ch, errors="ignore")
            raw = p[0] if p else "?"
            out.append(f"{raw}<{fold_syl(raw)}>" if raw != fold_syl(raw) else f"{raw}")
        else:
            out.append(ch)
    return " ".join(out)


class Encoder:
    """ids: 折叠音节 → 位号(持久化); 未登记音节 → mask=None"""

    def __init__(self, ids: dict | None = None):
        self.ids = dict(ids or {})
        self._next = max(self.ids.values()) + 1 if self.ids else 0

    def ensure(self, syl: str) -> int:
        if syl not in self.ids:
            self.ids[syl] = self._next
            self._next += 1
        return self.ids[syl]

    def char_bit(self, ch: str):
        """单字符 → 位（int）；未登记音节 → None。

        [OPENCODE-SUBSTR] 2026-10-19：给 fastpath.route_prefix 的"全子串扫描"用。
        与 mask() 的区别：mask() 是对整串做 OR、并可按 assign 登记新音节；
        这里只取【一个字符的位】，让调用方能在 O(n²) 子串枚举里【增量 OR】，
        不必为每个子串重新跑 pypinyin。
        """
        nsyl = max(self.ids.values()) + 1 if self.ids else 0
        syl = syllable_of(ch)
        if syl is None:
            # ASCII 字母/数字 → 独立 token（与 mask() 完全一致，勿另造规则）
            if ch.isascii() and ch.isalnum():
                syl = "A:" + ch.lower()
            else:
                cp = ord(ch)
                res_bits = 128 - nsyl if nsyl else 96
                res_mask = (1 << max(res_bits, 8)) - 1
                return ((cp * 0x9E3779B1) & res_mask) << nsyl
        sid = self.ids.get(syl)
        return None if sid is None else (1 << sid)

    def mask(self, text: str, assign: bool = False):
        m = 0
        nsyl = max(self.ids.values()) + 1 if self.ids else 0
        for ch in text:
            syl = syllable_of(ch)
            if syl is None:
                # ★★ 血债（2026-10-19 用户实测）：ASCII 字母/数字原来被塞进"剩余位散列
                #   字段"（同一段位里 OR 多个字符的散列）→ 字符一多该字段就【饱和】，
                #   于是「启动Blender」和「启动PowerShell」掩码完全相同 →
                #   打开/启动任何英文名程序都命中第一个（实测「启动Blender」开了 PowerShell）。
                #   现在：ASCII 字母/数字当成【独立 token】（每个字符一个位），掩码可区分。
                if ch.isascii() and ch.isalnum():
                    syl = "A:" + ch.lower()
                else:
                    cp = ord(ch)
                    res_bits = 128 - nsyl if nsyl else 96
                    res_mask = (1 << max(res_bits, 8)) - 1
                    m |= ((cp * 0x9E3779B1) & res_mask) << nsyl
                    continue
            sid = self.ids.get(syl)
            if sid is None:
                if assign:
                    sid = self.ensure(syl)
                else:
                    return None          # 未见音节 → MISS(不猜)
            m |= 1 << sid
        return m

    def pinyin(self, text: str) -> str:
        return " ".join((lazy_pinyin(ch, errors="ignore") or ["?"])[0]
                        if "\u4e00" <= ch <= "\u9fff" else ch for ch in text)
